package com.alsafa.native4;
import android.app.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import com.alsafa.native4.core.*;import java.util.*;
public final class QuickRepairButtonsActivity extends Activity{
 private Native4Services s;private EditText search,label,icon;private Spinner results;private LinearLayout list;private TextView status;private final ArrayList<RepairPartStore.SearchResult> found=new ArrayList<>();private final Handler h=new Handler(Looper.getMainLooper());private Runnable pending;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_quick_repair_buttons);CoreDb db=new CoreDb(this);s=new Native4Services(db,DeviceIdentity.get(this));search=findViewById(R.id.quickButtonPartSearch);label=findViewById(R.id.quickButtonLabel);icon=findViewById(R.id.quickButtonIcon);results=findViewById(R.id.quickButtonPartResults);list=findViewById(R.id.quickButtonList);status=findViewById(R.id.quickButtonStatus);findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.quickButtonSave).setOnClickListener(v->save());search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int a,int c,int d){}public void onTextChanged(CharSequence x,int a,int b,int c){if(pending!=null)h.removeCallbacks(pending);pending=()->lookup();h.postDelayed(pending,325);}public void afterTextChanged(Editable e){}});refresh();}
 private void lookup(){found.clear();found.addAll(s.repairParts.search(search.getText().toString(),30));ArrayList<String> names=new ArrayList<>();for(RepairPartStore.SearchResult r:found)names.add(r.name+" — المتاح "+r.quantity+(r.barcode==null||r.barcode.isEmpty()?"":" — "+r.barcode));if(names.isEmpty())names.add("لا توجد نتائج");results.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));}
 private void save(){try{int p=results.getSelectedItemPosition();if(found.isEmpty()||p<0||p>=found.size())throw new IllegalArgumentException("اختر قطعة صيانة صحيحة");String l=label.getText().toString().trim(),i=icon.getText().toString().trim();s.quickRepairButtons.save("",l,i,found.get(p).partId,s.quickRepairButtons.active().size());label.setText("");icon.setText("");status.setText("✓ تم إنشاء الزر وربطه بـ "+found.get(p).name);refresh();}catch(Exception e){status.setText("لم يُحفظ الزر: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}}
 private void refresh(){list.removeAllViews();for(QuickRepairButtonStore.Item x:s.quickRepairButtons.active()){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button off=new Button(this);off.setText("تعطيل");off.setOnClickListener(v->{s.quickRepairButtons.disable(x.id);refresh();});TextView t=new TextView(this);t.setText(x.icon+" "+x.label+" ← "+x.partName+" | المتاح "+x.quantity);t.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);row.addView(off);row.addView(t,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));list.addView(row);}}
}